import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ExcelParser {

    public static void main(String[] args) throws IOException {
        String filePath = "path/to/your/excel/file.xlsx";
        FileInputStream excelFile = new FileInputStream(new File(filePath));

        Workbook workbook = new XSSFWorkbook(excelFile);
        Sheet sheet = workbook.getSheetAt(0); // Assuming the data is in the first sheet
        List<ModelActionWrapper<Campaign>> campaignWrappers = new ArrayList<>();
        List<ModelActionWrapper<AdGroup>> adGroupWrappers = new ArrayList<>();
        // Add more lists for other domain models

        // Read the header row and create column mappings
        Row headerRow = sheet.getRow(0);
        ColumnMapping columnMapping = new ColumnMapping();

        for (Cell headerCell : headerRow) {
            String columnName = headerCell.getStringCellValue().trim();
            int columnIndex = headerCell.getColumnIndex();
            columnMapping.addColumn(columnName, columnIndex);
        }

        // Parse the rows and create domain models with actions
        for (int rowIndex = 1; rowIndex <= sheet.getLastRowNum(); rowIndex++) {
            Row row = sheet.getRow(rowIndex);

            String objectType = getStringCellValue(row, columnMapping.getColumnIndex("object_type"));

            if (objectType == null) {
                continue; // Skip rows with an empty object type
            }

            switch (objectType.toLowerCase()) {
                case "campaign":
                    ModelActionWrapper<Campaign> campaignWrapper = parseCampaignWrapper(row, columnMapping);
                    campaignWrappers.add(campaignWrapper);
                    break;
                case "adgroup":
                    ModelActionWrapper<AdGroup> adGroupWrapper = parseAdGroupWrapper(row, columnMapping);
                    adGroupWrappers.add(adGroupWrapper);
                    break;
                // Add more cases for other domain models
                default:
                    throw new IllegalArgumentException("Invalid object type: " + objectType);
            }
        }

        // Process the domain models with actions (e.g., create command objects and execute them)
        // ...

        workbook.close();
        excelFile.close();
    }

    private static ModelActionWrapper<Campaign> parseCampaignWrapper(Row row, ColumnMapping columnMapping) {
        String campaignId = getStringCellValue(row, columnMapping.getColumnIndex("campaign_id"));
        String campaignName = getStringCellValue(row, columnMapping.getColumnIndex("campaign_name"));
        String campaignState = getStringCellValue(row, columnMapping.getColumnIndex("campaign_state"));
        double campaignBudget = getNumericCellValue(row, columnMapping.getColumnIndex("campaign_budget"));
        String campaignAction = getStringCellValue(row, columnMapping.getColumnIndex("campaign_action"));

        Campaign campaign = new Campaign(campaignId, campaignName, campaignState, campaignBudget);
        return new ModelActionWrapper<>(campaignAction, campaign);
    }
