<?php

require_once __DIR__ . '/../models/User.php';

class Authentication {
    private $user_model;

    public function __construct() {
        $this->user_model = new User();
    }

    public function authenticate($request) {
        $auth_header = isset($request['headers']['Authorization']) ? $request['headers']['Authorization'] : null;

        if (!$auth_header) {
            http_response_code(401);
            echo json_encode(["error" => "Unauthorized access, missing Authorization header."]);
            exit();
        }

        $token = str_replace("Bearer ", "", $auth_header);

        try {
            $decoded = JWT::decode($token, SECRET_KEY, ['HS256']);
            $user = $this->user_model->getById($decoded->data->id);

            if (!$user) {
                http_response_code(401);
                echo json_encode(["error" => "Unauthorized access, invalid token."]);
                exit();
            }

            return $user;
        } catch (Exception $e) {
            http_response_code(401);
            echo json_encode(["error" => "Unauthorized access, invalid token. " . $e->getMessage()]);
            exit();
        }
    }
}

?>
