grammar RuleEngine;

rule: 'WHEN' condition 'THEN' action;
condition: expression (logical_operator expression)*;
expression: variable comparison_operator value;
variable: IDENTIFIER;
comparison_operator: '>' | '<' | '>=' | '<=' | '==' | '!=';
value: NUMBER | STRING | BOOLEAN;
logical_operator: 'AND' | 'OR' | 'NOT';

IDENTIFIER: [a-zA-Z_] [a-zA-Z0-9_]*;
NUMBER: [0-9]+ ('.' [0-9]+)?;
