        if (rows != cols) {
            Matrix<T> temp_matrix(*this);
            resize(cols, rows);
            copy_data(temp_matrix, true);
        } else {
            for (size_t i = 0; i < rows; i++) {
                for (size_t j = i + 1; j < cols; j++) {
