Here's an example of how you can load remote entry files on demand:

1. Create a helper function to load the remote entry file:
```javascript
// src/loadRemoteEntry.js

async function loadRemoteEntry(remoteConfig) {
  return new Promise(async (resolve, reject) => {
    const { scope, url } = remoteConfig;

    if (!window[scope]) {
      try {
        const script = document.createElement('script');
        script.src = url;
        script.type = 'text/javascript';
        script.async = true;
        script.onload = () => {
          resolve(window[scope]);
        };
        script.onerror = () => {
          reject(new Error(`Failed to load remote entry: ${url}`));
        };
        document.head.appendChild(script);
      } catch (error) {
        reject(error);
      }
    } else {
      resolve(window[scope]);
    }
  });
}
export default loadRemoteEntry;
```
1. Create a function to dynamically load remote components using the helper function:
```javascript
// src/loadRemoteComponent.js

import loadRemoteEntry from './loadRemoteEntry';

async function loadRemoteComponent(remoteConfig, moduleName) {
  const { scope, module: modulePath } = remoteConfig;

  await loadRemoteEntry(remoteConfig);

  await __webpack_init_sharing__('default');
  const container = window[scope];
  await container.init(__webpack_share_scopes__.default);

  const factory = await container.get(modulePath);
  const Module = factory();

  return Module[moduleName];
}
export default loadRemoteComponent;
```
1. Use the `loadRemoteComponent` function to dynamically load remote components:
```javascript
// src/index.js

import React, { lazy, Suspense } from 'react';
import ReactDOM from 'react-dom';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import loadRemoteComponent from './loadRemoteComponent';

const NavHeader = lazy(() =>
  loadRemoteComponent({ scope: 'nav_header', module: './NavHeader', url: 'http://localhost:3001/remoteEntry.js' }, 'NavHeader')
);

// ... other components with similar dynamic imports

const App = () => (
  <Router>
    <Suspense fallback={<div>Loading...</div>}>
      <NavHeader />
      {/* ... other components */}
    </Suspense>
  </Router>
);

ReactDOM.render(<App />, document.getElementById('root'));
```
In this example, the `loadRemoteComponent` function takes a configuration object with the `scope`, `module`, and `url` properties. The `scope` and `module` properties are used by Webpack Module Federation to resolve the remote components, and the `url` property is the URL of the remote entry file.

The `loadRemoteEntry` function is responsible for loading the remote entry file only when needed. It checks if the remote entry file is already loaded (by checking `window[scope]`), and if not, it adds a script tag to load the remote entry file.

By using this approach, the remote entry files are fetched on-demand, only when their corresponding components are needed. This will prevent the remote entry files from being fetched on the initial load of the `host-app` and can help further optimize your application's performance.

However, keep in mind that this approach might increase the complexity of your application and can be harder to maintain compared to the standard Webpack Module Federation setup.

