To take a screenshot of the entire email message, including the parts hidden from scrolling, on the desktop Outlook app on Windows without using the "robotjs" module, you can use the "node-desktop-screenshot" and "sharp" modules in combination with the "windows-activity-enumerator" module to programmatically scroll the email message and capture multiple screenshots. Here's an example code snippet:
```javascript
const screenshot = require('node-desktop-screenshot');
const sharp = require('sharp');
const ActivityEnumerator = require('windows-activity-enumerator');

// Set the position and size of the email message area
const messageArea = {
  x: 100, // Replace with the x-coordinate of the top-left corner of the email message area
  y: 100, // Replace with the y-coordinate of the top-left corner of the email message area
  width: 800, // Replace with the width of the email message area
  height: 600, // Replace with the height of the email message area
};

// Set the amount of scrolling for each screenshot
const scrollAmount = 100; // Replace with the amount of scrolling in pixels

// Calculate the number of screenshots needed
const numScreenshots = Math.ceil(messageArea.height / scrollAmount);

// Create an ActivityEnumerator object to find the Outlook window
const ae = new ActivityEnumerator();
ae.getWindows((windows) => {
  const outlookWindow = windows.find((w) => w.path && w.path.includes('OUTLOOK.EXE'));

  if (!outlookWindow) {
    console.error('Could not find the Outlook window');
    return;
  }

  // Set the Outlook window to be the foreground window
  ae.setForegroundWindow(outlookWindow.id);

  // Wait for the window to become active before taking screenshots
  setTimeout(() => {
    // Take the first screenshot of the email message area
    screenshot().then((imageBuffer) => {
      // Crop the screenshot to the email message area
      let emailScreenshot = sharp(imageBuffer)
        .extract({
          left: messageArea.x,
          top: messageArea.y,
          width: messageArea.width,
          height: messageArea.height,
        })
        .toBuffer();

      // Scroll the email message and take additional screenshots
      for (let i = 1; i < numScreenshots; i++) {
        ae.sendInput({ type: 'keydown', key: 'down' });
        ae.sendInput({ type: 'keyup', key: 'down' });

        // Wait for the window to redraw before taking the screenshot
        setTimeout(() => {
          screenshot().then((imageBuffer) => {
            // Crop the screenshot to the portion below the previous screenshot
            const topOffset = i * scrollAmount;
            emailScreenshot = emailScreenshot.then((prevBuffer) =>
              sharp(imageBuffer)
                .extract({
                  left: messageArea.x,
                  top: messageArea.y + topOffset,
                  width: messageArea.width,
                  height: messageArea.height - topOffset,
                })
                .toBuffer()
                .then((currentBuffer) => Buffer.concat([prevBuffer, currentBuffer]))
            );
            if (i === numScreenshots - 1) {
              // Save the full email screenshot as a PNG file
              emailScreenshot.then((emailBuffer) => {
                sharp(emailBuffer).png().toFile('email-screenshot.png', (err, info) => {
                  if (err) {
                    console.error(err);
                  } else {
                    console.log('Screenshot saved as email-screenshot.png');
                  }
                });
              });
            }
          });
        }, 100);
      }
    });
  }, 1000);
});
