#include <vector>
#include <queue>

class MyGraph {
public:
    MyGraph(int num);
    void addEdge(int source, int target, float weight);
    void printGraph(std::ostream& out);
    void debugGraph();
    void findMaximumSpanningTree();

private:
    int numVerticies = 0;
    std::unordered_map<int, std::list<std::pair<int, float>>> graph;
    std::unordered_map<int, std::list<std::pair<int, float>>> maximumSpanningTree;
};

void MyGraph::findMaximumSpanningTree() {
    maximumSpanningTree.clear();

    // Create a priority queue of pairs (weight, vertex) to keep track of the edges with minimum weight
    std::priority_queue<std::pair<float, int>> pq;

    // Create a vector to keep track of which vertices have been visited
    std::vector<bool> visited(numVerticies, false);

    // Start from vertex 0 and mark it as visited
    visited[0] = true;

    // Add all edges incident to vertex 0 to the priority queue
    for (auto& edge : graph[0]) {
        pq.push({ edge.second, edge.first });
    }

    // Continue adding edges until we have visited all vertices or the priority queue is empty
    while (!pq.empty()) {
        // Get the edge with minimum weight from the priority queue
        auto edge = pq.top();
        pq.pop();

        // If the vertex at the other end of the edge has not been visited yet, add the edge to the maximum spanning tree
        if (!visited[edge.second]) {
            int source = std::min(0, edge.second);
            int target = std::max(0, edge.second);
            float weight = edge.first;
            maximumSpanningTree[source].push_back({ target, weight });
            maximumSpanningTree[target].push_back({ source, weight });

            // Mark the vertex as visited
            visited[edge.second] = true;

