```scss
function sort_and_position(arr) {
  const n = arr.length;
  const position_indexes = Array(n).fill(null);
  const position_values = Array(n).fill(null);

  for (let i = 0; i < n; i++) {
    position_indexes[i] = i;
    position_values[i] = arr[i].position;
  }

  position_indexes.sort((a, b) => position_values[a] - position_values[b]);

  const result = Array(n).fill(null);
  let add_to_last = [];

  for (let i = 0; i < n; i++) {
    let curr = arr[position_indexes[i]];
    if (curr.position <= n) {
      result[curr.position - 1] = curr;
    } else {
      add_to_last.push(curr);
    }
  }

  add_to_last.sort((a, b) => a.position - b.position);

  for (let i = 0; i < n; i++) {
    if (result[i] === null) {
      result[i] = add_to_last.shift();
    }
  }

  for (let i = 0; i < n; i++) {
    if (arr[i].randomize) {
      const random_index = Math.floor(Math.random() * n);
      [result[i], result[random_index]] = [result[random_index], result[i]];
    }
  }

  return result;
}
