Certainly! To add a row without including the time component, we need to set the time portion of the date object to 00:00:00 (midnight) before adding it to the "balance sheet." We can achieve this using the `setHours` method in JavaScript. Here's the updated `onEdit` function with this change:
```javascript
function onEdit(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var dashboardSheet = ss.getSheetByName("dashboard");
  var balanceSheet = ss.getSheetByName("balance sheet");
  var tasksSheet = ss.getSheetByName("tasks");
  var editedRange = e.range;

  // Check if the edited cell is within the data range of the dashboard sheet
  if (editedRange.getSheet().getName() === "dashboard" &&
      editedRange.getRow() >= 6 && editedRange.getRow() <= 20 &&
      editedRange.getColumn() >= 4 && editedRange.getColumn() <= 34) {
    var date = editedRange.getColumn() - 3;
    var taskId = dashboardSheet.getRange(editedRange.getRow(), 2).getValue();
    var taskName = dashboardSheet.getRange(editedRange.getRow(), 3).getValue();

    // Look up the points from the "tasks" sheet using the task ID
    var taskData = tasksSheet.getRange("B2:G" + tasksSheet.getLastRow()).getValues();
    var points = taskData.find(row => row[0] === taskId)[5]; // Column G (index 5) contains the points

    var balanceData = balanceSheet.getRange("B2:E" + balanceSheet.getLastRow()).getValues();
    var dateObj = new Date();
    dateObj.setDate(date);
    dateObj.setHours(0, 0, 0, 0); // Set the time portion to 00:00:00 (midnight)

    if (e.value === "TRUE") {
      // Add a new row to the balance sheet with the correct points value and date without time
      balanceSheet.appendRow([null, dateObj, taskId, taskName, points, null]);
    } else {
      // Remove the corresponding row from the balance sheet
      for (var i = 0; i < balanceData.length; i++) {
        if (balanceData[i][0] instanceof Date && 
            Utilities.formatDate(balanceData[i][0], ss.getSpreadsheetTimeZone(), "d") == date &&
            balanceData[i][1] === taskId) {
          balanceSheet.deleteRow(i + 2);
          break;
        }
      }
    }
  }
}
```
The line `dateObj.setHours(0, 0, 0, 0);` sets the hours, minutes, seconds, and milliseconds of the `dateObj` to 00:00:00, effectively removing the time portion of the date. With this change, the script will add the date without the time when adding a new row to the "balance sheet."

This update should ensure that only the date is added to the "balance sheet" without the time component.

