Here's the complete 'app.py' file using the sklearn library instead of gensim:
```python
import json
from flask import Flask, render_template, request, jsonify
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np

app = Flask(__name__)

# Load GloVe embeddings
def load_glove_embeddings(file_path):
    embeddings = {}
    with open(file_path, 'r', encoding='utf-8') as file:
        for line in file:
            values = line.strip().split()
            word = values[0]
            vector = np.asarray(values[1:], dtype='float32')
            embeddings[word] = vector
    return embeddings

glove_model = load_glove_embeddings('glove.6B.50d.txt')

# Load 1000 most common nouns
with open('common_nouns.txt', 'r') as f:
    common_nouns = [line.strip() for line in f]

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/generate_puzzle', methods=['GET'])
def generate_puzzle():
    word1, word2, operation = generate_random_puzzle(common_nouns)
    word1_embedding = glove_model[word1]
    word2_embedding = glove_model[word2]

    if operation == '+':
        result_embedding = word1_embedding + word2_embedding
    else:
        result_embedding = word1_embedding - word2_embedding

    return jsonify({
        'word1': word1,
        'word2': word2,
        'operation': operation,
        'result_embedding': result_embedding.tolist(),
    })

def generate_random_puzzle(words):
    word1 = np.random.choice(words)
    word2 = np.random.choice(words)
    operation = '+' if np.random.rand() > 0.5 else '-'
    return word1, word2, operation

@app.route('/calculate_similarity', methods=['POST'])
def calculate_similarity():
    user_word = request.form['user_word']
    result_embedding = json.loads(request.form['result_embedding'])

    if user_word not in glove_model:
        return jsonify({'error': 'Word not found in GloVe embeddings'})

    user_word_embedding = glove_model[user_word]
    similarity = cosine_similarity([user_word_embedding], [result_embedding])[0][0]

    nearest_neighbor_word = find_nearest_neighbor(result_embedding)

    return jsonify({'similarity': similarity, 'nearest_neighbor_word': nearest_neighbor_word})

def find_nearest_neighbor(embedding):
    max_similarity = -1
    nearest_word = None

    for word, vec in glove_model.items():
        similarity = cosine_similarity([embedding], [vec])[0][0]
        if similarity > max_similarity:
            max_similarity = similarity
            nearest_word = word

    return nearest_word

if __name__ == '__main__':
    app.run(debug=True)
```
Please make sure you have the 'glove.6B.50d.txt' and 'common\_nouns.txt' files in the same directory as 'app.py'. This version of 'app.py' uses the sklearn library to compute cosine similarity and does not rely on the gensim library.

