Here is an example of how the op code operations could be implemented inline in the `Execute` method:
```
public void Execute()
{
    while (programCounter < program.Count)
    {
        var instruction = program[programCounter];
        programCounter++;

        switch (instruction.OpCode)
        {
            case OpCode.ADD:
                stack.Push(stack.Pop() + stack.Pop());
                break;
            case OpCode.SUB:
                stack.Push(stack.Pop() - stack.Pop());
                break;
            case OpCode.MUL:
                stack.Push(stack.Pop() * stack.Pop());
                break;
            case OpCode.DIV:
                stack.Push(stack.Pop() / stack.Pop());
                break;
            case OpCode.MOD:
                stack.Push(stack.Pop() % stack.Pop());
                break;
            case OpCode.POW:
                stack.Push(Math.Pow(stack.Pop(), stack.Pop()));
                break;
            case OpCode.SIN:
                stack.Push(Math.Sin(stack.Pop()));
                break;
            case OpCode.COS:
                stack.Push(Math.Cos(stack.Pop()));
                break;
            case OpCode.TAN:
                stack.Push(Math.Tan(stack.Pop()));
                break;
            case OpCode.LOG:
                stack.Push(Math.Log(stack.Pop()));
                break;
            case OpCode.EXP:
                stack.Push(Math.Exp(stack.Pop()));
                break;
            case OpCode.ABS:
                stack.Push(Math.Abs(stack.Pop()));
                break;
            case OpCode.NEG:
                stack.Push(-stack.Pop());
                break;
            case OpCode.IF:
                if (stack.Pop() == 0)
                {
                    programCounter++;
                }
                break;
            case OpCode.JMP:
                programCounter = instruction.Operand;
                break;
            case OpCode.CALL:
                stack.Push(programCounter);
                programCounter = instruction.Operand;
                break;
            case OpCode.RET:
                programCounter = (int)stack.Pop();
                break;
            case OpCode.LOAD:
                stack.Push(memory[instruction.Operand]);
                break;
            case OpCode.STORE:
                memory[instruction.Operand] = stack.Pop();
                break;
        }
    }
}
```
