function getSequences(inputArray) {
  let result = [];
  let used = [];
  let n = inputArray.length;

  function generate(level) {
    if (level === n) {
      if (isUniqueSequence(result[result.length - 1])) {
        result.push([...used]);
      }
      return;
    }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = inputArray[i];
      generate(level + 1);
      used[i] = null;
    }
  }

  function isUniqueSequence(seq) {
    let reversed = seq.slice().reverse();
    let rotated = seq.slice(1).concat(seq[0]);
    for (let i = 0; i < n; i++) {
      if (reversed.every((val, index) => val === seq[index])) {
        return false;
      }
      rotated = rotated.slice(1).concat(rotated[0]);
      if (rotated.every((val, index) => val === seq[index])) {
        return false;
      }
    }
    return true;
  }

  generate(0);
  return result;
}
