func ScanDocs(dir string, re *regexp.Regexp, debug bool) error {
	return filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if info.IsDir() && level(path, dir) == 5 {
			files, nonMatchingFiles, err := filterFiles(path, re, debug)
			if err != nil {
				return err
			}

			format, section, region, supplier, err := getParentDirs(path)
			if err != nil {
				return err
			}

			ProcessDocs(debug, format, section, region, supplier, files, nonMatchingFiles)
		}

		return nil
	})
}

func filterFiles(dir string, re *regexp.Regexp, debug bool) ([]string, []string, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*"))
	if err != nil {
		return nil, nil, err
	}

	matchingFiles := make([]string, 0, len(files))
	nonMatchingFiles := make([]string, 0, len(files))
	for _, file := range files {
		if re.MatchString(file) {
			matchingFiles = append(matchingFiles, file)
		} else {
			nonMatchingFiles = append(nonMatchingFiles, file)
		}
	}

	return matchingFiles, nonMatchingFiles, nil
}

func level(path, root string) int {
	return len(filepath.SplitList(filepath.Clean(strings.TrimPrefix(path, root))))
}

func getParentDirs(path string) (string, string, string, string, error) {
	parent := filepath.Dir(path)
	supplier := filepath.Base(parent)
