private string GetIndexFilePath(int blockNumber)
{
    return $"{_filePrefix}_index_{blockNumber}.bin";
}

private void LoadIndexCache(int blockNumber)
{
    string indexFilePath = GetIndexFilePath(blockNumber);
    using (FileStream indexFileStream = new FileStream(indexFilePath, FileMode.OpenOrCreate, FileAccess.Read, FileShare.None))
    using (BinaryReader indexFileReader = new BinaryReader(indexFileStream))
    {
        int itemCount = (int)(indexFileStream.Length / (sizeof(long) + sizeof(long)));
        IndexEntry[] indexCache = new IndexEntry[itemCount];
        for (int i = 0; i < itemCount; i++)
        {
            indexCache[i].DataFileOffset = indexFileReader.ReadInt64();
            indexCache[i].Timestamp = new DateTime(indexFileReader.ReadInt64());
        }
        _indexCaches[blockNumber - _firstBlockNumber] = indexCache;
    }
}

private void LoadIndexCaches()
{
    int numberOfBlocks = _lastBlockNumber - _firstBlockNumber + 1;
    _indexCaches = new IndexEntry[numberOfBlocks][];

    for (int blockNumber = _firstBlockNumber; blockNumber <= _lastBlockNumber; blockNumber++)
    {
        LoadIndexCache(blockNumber);
    }
}

private void SaveIndexCache(int blockNumber)
{
    string indexFilePath = GetIndexFilePath(blockNumber);
    using (FileStream indexFileStream = new FileStream(indexFilePath, FileMode.Create, FileAccess.Write, FileShare.None))
    using (BinaryWriter indexFileWriter = new BinaryWriter(indexFileStream))
    {
        IndexEntry[] indexCache = _indexCaches[blockNumber - _firstBlockNumber];
        for (int i = 0; i < indexCache.Length; i++)
        {
            indexFileWriter.Write(indexCache[i].DataFileOffset);
            indexFileWriter.Write(indexCache[i].Timestamp.Ticks);
        }
    }
}
